%%{init: {
  'theme': 'base',
  'themeVariables': {
    'fontFamily': 'system-ui, -apple-system, "Noto Sans SC", "PingFang SC", sans-serif',
    'fontSize': '14px',
    'lineColor': '#6B7280',
    'primaryTextColor': '#212529'
  },
  'flowchart': {
    'nodeSpacing': 24,
    'rankSpacing': 28,
    'curve': 'linear',
    'padding': 12
  }
}}%%
flowchart TD
n0("Pretraining:<br/>massive<br/>general<br/>corpus -&gt;<br/>base model<br/>(general<br/>language<br/>ability)")
    n1("Finetuning:<br/>small domain-<br/>specific data<br/>-&gt; same model<br/>+ delta patch<br/>(domain/<br/>format/style<br/>ability)")
    n2("Pretraining<br/>provides the<br/>foundation,<br/>finetuning<br/>adds<br/>specialization")
    n0 --> n1
    n1 --> n2

    classDef neutral fill:#F8FBFF,stroke:#93C5FD,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef root fill:#E9D5FF,stroke:#C4B5FD,stroke-width:1.5px,color:#212529,rx:6,ry:6,font-weight:bold;
    classDef category fill:#DBEAFE,stroke:#93C5FD,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef leaf fill:#F1F3F5,stroke:#ADB5BD,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef input fill:#FBE4D5,stroke:#E9B08A,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef output fill:#D1FAE5,stroke:#86EFAC,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef warning fill:#FEF3C7,stroke:#FCD34D,stroke-width:1.5px,color:#212529,rx:6,ry:6;
    classDef error fill:#FECACA,stroke:#F87171,stroke-width:1.5px,color:#212529,rx:6,ry:6;

    class n0 input;
    class n2 output;
    class n1 leaf;

    linkStyle default stroke:#6B7280,stroke-width:1.5px;
